-- Rename per-minute columns to per-hour in cloudInstances
ALTER TABLE cloudInstances 
  CHANGE COLUMN pricePerMinute pricePerHour DECIMAL(10,4) NOT NULL DEFAULT 0;

-- Rename per-minute columns to per-hour in gpuInstances
ALTER TABLE gpuInstances 
  CHANGE COLUMN pricePerMinute pricePerHour DECIMAL(10,4) NOT NULL DEFAULT 0;

-- Rename per-minute columns to per-hour in billingRecords
ALTER TABLE billingRecords 
  CHANGE COLUMN minutesBilled hoursBilled DECIMAL(8,2) NOT NULL,
  CHANGE COLUMN pricePerMinute pricePerHour DECIMAL(12,6) NOT NULL;
